  let presentationTimerInterval = null;
  let presentationStartTime = null;
  let displayMonitorInterval = null;

  function startPresentationTimer() {
    if (!presentationStartTime) {
      presentationStartTime = Date.now();
    }
    if (presentationTimerInterval) clearInterval(presentationTimerInterval);
    
    presentationTimerInterval = setInterval(() => {
      if (!state.selectedScreen) {
        stopPresentationTimer();
        return;
      }
      const el = document.getElementById('display-pill-timer');
      if (el && presentationStartTime) {
        const elapsedSecs = Math.floor((Date.now() - presentationStartTime) / 1000);
        const hrs = Math.floor(elapsedSecs / 3600);
        const mins = Math.floor((elapsedSecs % 3600) / 60);
        const secs = elapsedSecs % 60;
        const timeStr = hrs > 0 
          ? `${String(hrs).padStart(2, '0')}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
          : `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
        el.innerHTML = `<span class="live-dot"></span> ${timeStr}`;
      }
    }, 1000);
  }

  function stopPresentationTimer() {
    if (presentationTimerInterval) {
      clearInterval(presentationTimerInterval);
      presentationTimerInterval = null;
    }
    presentationStartTime = null;
  }

  let lastWindowOpenTime = 0;

  function startDisplayMonitor() {
    if (displayMonitorInterval) {
      clearInterval(displayMonitorInterval);
      displayMonitorInterval = null;
    }
  }

  function closeActiveDisplay() {
    if (presenterWindow && !presenterWindow.closed) {
      try { presenterWindow.close(); } catch(e) {}
    }
    presenterWindow = null;
    if (els.obsOverlay) {
      els.obsOverlay.classList.add('hidden');
      if (document.fullscreenElement && document.exitFullscreen) {
        document.exitFullscreen().catch(() => {});
      }
    }
    state.selectedScreen = null;
    stopPresentationTimer();
    if (displayMonitorInterval) {
      clearInterval(displayMonitorInterval);
      displayMonitorInterval = null;
    }
    try { localStorage.removeItem('sunday_school_taranim_locked_screen'); } catch(e) {}
    updateDisplayButtonUI();
  }

  function updateDisplayButtonUI() {
    const container = document.getElementById('btn-menu-cast-wrapper');
    if (!container) return;

    const isExternalActive = Boolean(presenterWindow && !presenterWindow.closed);

    if (isExternalActive) {
      if (!presentationStartTime) {
        presentationStartTime = Date.now();
      }
      if (presentationTimerInterval) clearInterval(presentationTimerInterval);

      container.innerHTML = `
        <div id="active-cast-pill" class="active-cast-pill">
          <button type="button" id="btn-menu-cast" class="cast-live-badge-icon" title="البث والشاشات (فتح القائمة)">
            <span class="cast-live-dot"></span>
            <i class="fa-solid fa-tv"></i>
          </button>
          <span id="display-pill-timer" class="cast-timer-text">00:00</span>
          <button type="button" id="btn-close-cast-window" class="btn-close-cast-pill" title="إغلاق شاشة العرض الخارجي">
            <i class="fa-solid fa-xmark"></i>
          </button>
        </div>
      `;

      const closeBtn = document.getElementById('btn-close-cast-window');
      if (closeBtn) {
        closeBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          closeActiveDisplay();
        });
      }

      const castBtn = document.getElementById('btn-menu-cast');
      if (castBtn) {
        castBtn.addEventListener('click', async (e) => {
          e.stopPropagation();
          if ('getScreenDetails' in window && !screenDetails) {
            try { screenDetails = await window.getScreenDetails(); } catch(err) {}
          }
          const willShow = els.popoverCast.classList.contains('hidden');
          closeAllPopovers(els.popoverCast);
          if (willShow) {
            els.popoverCast.classList.remove('hidden');
            renderScreenOptions();
          } else {
            els.popoverCast.classList.add('hidden');
          }
        });
      }

      presentationTimerInterval = setInterval(() => {
        if (!presenterWindow || presenterWindow.closed) {
          closeActiveDisplay();
          return;
        }
        const el = document.getElementById('display-pill-timer');
        if (el && presentationStartTime) {
          const elapsedSecs = Math.floor((Date.now() - presentationStartTime) / 1000);
          const hrs = Math.floor(elapsedSecs / 3600);
          const mins = Math.floor((elapsedSecs % 3600) / 60);
          const secs = elapsedSecs % 60;
          const timeStr = hrs > 0 
            ? `${String(hrs).padStart(2, '0')}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
            : `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
          el.textContent = timeStr;
        }
      }, 1000);

      if (!displayMonitorInterval) {
        displayMonitorInterval = setInterval(() => {
          if (!presenterWindow || presenterWindow.closed) {
            closeActiveDisplay();
          }
        }, 800);
      }
    } else {
      stopPresentationTimer();
      if (displayMonitorInterval) {
        clearInterval(displayMonitorInterval);
        displayMonitorInterval = null;
      }
      container.innerHTML = `
        <button class="icon-menu-btn" id="btn-menu-cast" title="البث والشاشات الخارجية (TV / OBS)" type="button">
          <i class="fa-solid fa-tv"></i>
        </button>
      `;
      const castBtn = container.querySelector('#btn-menu-cast');
      if (castBtn) {
        castBtn.addEventListener('click', async (e) => {
          e.stopPropagation();
          if ('getScreenDetails' in window && !screenDetails) {
            try { screenDetails = await window.getScreenDetails(); } catch(err) {}
          }

          const willShow = els.popoverCast.classList.contains('hidden');
          closeAllPopovers(els.popoverCast);
          if (willShow) {
            els.popoverCast.classList.remove('hidden');
            renderScreenOptions();
          } else {
            els.popoverCast.classList.add('hidden');
          }
        });
      }
    }
  }

  function showExternalFullscreenNotice() {
    let noticeEl = document.getElementById('notice-ext-fs-modal');
    if (!noticeEl) {
      noticeEl = document.createElement('div');
      noticeEl.id = 'notice-ext-fs-modal';
      noticeEl.style.cssText = 'position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(15,23,42,0.65); backdrop-filter:blur(8px); z-index:99999; display:flex; align-items:center; justify-content:center; padding:20px; animation:fadeIn 0.2s ease;';
      noticeEl.innerHTML = `
        <div style="background:#ffffff; color:#0f172a; border-radius:16px; padding:24px 28px; max-width:440px; width:100%; text-align:center; box-shadow:0 20px 40px rgba(0,0,0,0.3); border:1px solid #e2e8f0; font-family:inherit;">
          <div style="width:52px; height:52px; background:#eff6ff; color:#2563eb; border-radius:50%; display:flex; align-items:center; justify-content:center; margin:0 auto 14px; font-size:1.5rem;">
            <i class="fa-solid fa-expand"></i>
          </div>
          <h3 style="margin:0 0 8px; font-size:1.15rem; font-weight:800; color:#1e293b;">فتح الشاشة الخارجية ملء الشاشة</h3>
          <p style="margin:0 0 18px; font-size:0.95rem; color:#475569; font-weight:600; line-height:1.6; display:flex; align-items:center; justify-content:center; flex-wrap:wrap; gap:4px;">
            اضغط على زر
            <kbd style="display:inline-flex; align-items:center; justify-content:center; min-width:38px; height:38px; padding:0 10px; background:linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%); border:1px solid #cbd5e1; border-bottom:3px solid #94a3b8; border-radius:8px; font-weight:800; font-size:1.2rem; color:#1e293b; font-family:monospace, inherit; box-shadow:0 2px 5px rgba(0,0,0,0.15); vertical-align:middle; margin:0 4px; user-select:none;">F</kbd>
            أو انقر على الشاشة الخارجية
          </p>
          <button type="button" id="btn-close-ext-notice" style="background:#2563eb; color:#ffffff; border:none; padding:10px 24px; border-radius:10px; font-weight:700; font-size:0.9rem; cursor:pointer; width:100%; transition:all 0.15s ease;">
            حسناً، فهمت
          </button>
        </div>
      `;
      document.body.appendChild(noticeEl);

      const closeBtn = noticeEl.querySelector('#btn-close-ext-notice');
      if (closeBtn) {
        closeBtn.addEventListener('click', () => hideExternalFullscreenNotice());
      }
    }
    noticeEl.classList.remove('hidden');
    noticeEl.style.display = 'flex';
  }

  function hideExternalFullscreenNotice() {
    const noticeEl = document.getElementById('notice-ext-fs-modal');
    if (noticeEl) {
      noticeEl.classList.add('hidden');
      noticeEl.style.display = 'none';
    }
  }

  broadcastChannel.onmessage = (event) => {
    if (event.data) {
      if (event.data.action === 'NEXT_SLIDE') {
        nextLine();
      } else if (event.data.action === 'PREV_SLIDE') {
        prevLine();
      } else if (event.data.action === 'EXTERNAL_FULLSCREEN_ACTIVATED') {
        window.focus();
        hideExternalFullscreenNotice();
      }
      if (event.data.type === 'UPDATE_POS' || event.data.pos) {
        if (event.data.pos) {
          state.dragPivot = event.data.pos;
          localStorage.setItem('sunday_school_taranim_drag_pivot', JSON.stringify(state.dragPivot));
        }
      }
    }
  };

  window.addEventListener('storage', (e) => {
    if (e.key === 'sunday_school_taranim_drag_pivot' && e.newValue) {
      try {
        state.dragPivot = JSON.parse(e.newValue);
      } catch (err) {}
    }
  });

